"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/crypto-markets/variants/02-order-book";
export interface ArtemisOrderBookProps { className?: string;  }
export function ArtemisOrderBook({ className }: ArtemisOrderBookProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

// @zeus-internal
import type { ReactElement } from "react";
const symbols = ["BTC","ETH","USDT","BNB","SOL","USDC","XRP","DOGE","TON","ADA","AVAX","LINK","DAI","UNI","PEPE","POL","ARB","AAVE","OP"];
const colors = ["#ed8b21","#7279dd","#009b87","#e9ba34","#7c53ca","#3277c6","#d75883","#4ba3bc"];
export const COIN_ICONS: Record<string, ReactElement> = Object.fromEntries(symbols.map((symbol, index) => [symbol, <svg key={symbol} viewBox="0 0 24 24" className="art:size-full" aria-hidden="true"><circle cx="12" cy="12" r="12" fill={colors[index % colors.length]}/><path d={index % 3 === 0 ? "M12 5 18 12 12 19 6 12Z" : index % 3 === 1 ? "M7 8h10v8H7zM12 5v14" : "M6 12h12M12 6v12"} fill="none" stroke="white" strokeWidth="1.7" strokeLinejoin="round"/></svg>]));

"use client";
// @zeus-internal
import { COIN_ICONS } from "./01-price-table/icons";
import { AnimatePresence, motion, useInView, type Transition } from "motion/react";
import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { INITIAL_ASKS, INITIAL_BEST_BID, INITIAL_BIDS, INITIAL_LAST, INITIAL_TRADES, TICK_MS, formatPrice, formatSize, formatUsd, rows, tick, type Book, type Row, } from "./02-order-book/book";
const ROW_STAGGER = 0.02;
const ROW_IN: Transition = { duration: 0.2, ease: ARTEMIS_EASE_OUT };
const BAR: Transition = { duration: 0.6, ease: ARTEMIS_EASE_OUT };
const FLASH: Transition = { duration: 0.5, times: [0, 0.12, 1], ease: "easeOut" };
const TRADE_IN: Transition = { duration: 0.3, ease: ARTEMIS_EASE_OUT, layout: { type: "spring", stiffness: 550, damping: 51, mass: 1 } };
const TAB_INDICATOR: Transition = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 };
const TAB_BUTTON = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:py-1.5 art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
const GROUPS = [
    { value: 1, label: "0.1" },
    { value: 5, label: "0.5" },
    { value: 10, label: "1.0" },
] as const;
type Group = (typeof GROUPS)[number]["value"];
type Panel = "book" | "trades";
type Hover = {
    side: "asks" | "bids";
    index: number;
} | null;
const INITIAL_BOOK: Book = {
    bestBid: INITIAL_BEST_BID,
    asks: INITIAL_ASKS.slice(),
    bids: INITIAL_BIDS.slice(),
    last: INITIAL_LAST,
    direction: "buy",
    trades: INITIAL_TRADES.slice(),
    seq: 0,
};
const SIDE_CLASS = {
    asks: "art:group art:text-rose-600 art:dark:text-rose-400",
    bids: "art:group art:text-emerald-700 art:dark:text-emerald-400",
} as const;
function Indicator({ id }: {
    id: string;
}) {
    return (<motion.span layoutId={id} layout="position" className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }} transition={TAB_INDICATOR}/>);
}
function LevelRow({ row, side, distance, scale, mounted, highlighted, onHover, }: {
    row: Row;
    side: "asks" | "bids";
    distance: number;
    scale: number;
    mounted: boolean;
    highlighted: boolean;
    onHover: (on: boolean) => void;
}) {
    const delay = mounted ? 0 : distance * ROW_STAGGER;
    const previous = useRef(row.size);
    const [flash, setFlash] = useState(0);
    useEffect(() => {
        if (previous.current !== row.size)
            setFlash((n) => n + 1);
        previous.current = row.size;
    }, [row.size]);
    return (<motion.tr className={SIDE_CLASS[side]} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ ...ROW_IN, delay }} onPointerEnter={() => onHover(true)} onPointerLeave={() => onHover(false)}>
      <td className="art:relative art:h-8 art:px-4 art:py-0">
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:left-1 art:inset-y-px art:w-[calc(300%-8px)] art:overflow-hidden art:rounded-sm">
          <motion.div className="art:absolute art:inset-0 art:origin-right art:overflow-hidden art:rounded-sm" initial={{ transform: "scaleX(0)", opacity: 0 }} animate={{ transform: `scaleX(${scale})`, opacity: 1 }} transition={{ ...BAR, delay }}>
            <div className="art:absolute art:inset-0 art:bg-current art:opacity-[0.12]"/>
          </motion.div>
          <motion.div key={flash} className="art:absolute art:inset-0 art:bg-current" initial={{ opacity: 0 }} animate={flash ? { opacity: [0, 0.1, 0] } : { opacity: 0 }} transition={FLASH}/>
          <div className={artemisCx("art:absolute art:inset-0 art:bg-current art:transition-opacity art:duration-150", highlighted ? "art:opacity-[0.08]" : "art:opacity-0 art:group-hover:opacity-[0.05]")}/>
        </div>
        <span className="art:relative">{formatPrice(row.price)}</span>
      </td>
      <td className="art:relative art:px-4 art:py-0 art:text-right art:text-foreground">{formatSize(row.size)}</td>
      <td className="art:relative art:px-4 art:py-0 art:text-right art:text-muted-foreground">{formatSize(row.total)}</td>
    </motion.tr>);
}
function SrHead() {
    return (<thead className="art:sr-only">
      <tr>
        <th scope="col">
          {"Price "}
          {"USDC"}
        </th>
        <th scope="col">
          {"Size "}
          {"ETH"}
        </th>
        <th scope="col">
          {"Cumulative total "}
          {"ETH"}
        </th>
      </tr>
    </thead>);
}
export default function CryptoMarketsOrderBook() {
    const id = useId();
    const [book, setBook] = useState<Book>(INITIAL_BOOK);
    const [group, setGroup] = useState<Group>(1);
    const [panel, setPanel] = useState<Panel>("book");
    const [hover, setHover] = useState<Hover>(null);
    const [mounted, setMounted] = useState(false);
    const groupRefs = useRef<(HTMLButtonElement | null)[]>([]);
    const bookRef = useRef<Book>(INITIAL_BOOK);
    const sectionRef = useRef<HTMLElement>(null);
    const inView = useInView(sectionRef, { amount: 0.1 });
    useEffect(() => {
        if (!inView)
            return;
        const timer = window.setInterval(() => {
            const next = tick(bookRef.current, Math.random, Date.now());
            bookRef.current = next;
            setBook(next);
        }, TICK_MS);
        return () => window.clearInterval(timer);
    }, [inView]);
    useEffect(() => {
        const settle = window.setTimeout(() => setMounted(true), 600);
        return () => window.clearTimeout(settle);
    }, []);
    const asks = rows(book, "asks", group);
    const bids = rows(book, "bids", group);
    const max = Math.max(asks[asks.length - 1]?.total ?? 0, bids[bids.length - 1]?.total ?? 0) || 1;
    const lastText = formatPrice(book.last);
    const direction = book.direction === "sell" ? "down" : "up";
    const spreadTenths = (asks[0]?.price ?? book.bestBid + 1) - (bids[0]?.price ?? book.bestBid);
    const spread = `${formatPrice(spreadTenths)} \u00B7 ${((spreadTenths / book.last) * 100).toFixed(3)}%`;
    const hovered = hover ? (hover.side === "asks" ? asks : bids).slice(0, hover.index + 1) : [];
    const filled = hovered.reduce((sum, row) => sum + row.size, 0);
    const cost = hovered.reduce((sum, row) => sum + (row.price / 10) * row.size, 0);
    const onGroupKey = (event: KeyboardEvent<HTMLDivElement>) => {
        const index = GROUPS.findIndex((g) => g.value === group);
        let next = index;
        if (event.key === "ArrowRight")
            next = (index + 1) % GROUPS.length;
        else if (event.key === "ArrowLeft")
            next = (index - 1 + GROUPS.length) % GROUPS.length;
        else
            return;
        event.preventDefault();
        setGroup(GROUPS[next]!.value);
        groupRefs.current[next]?.focus();
    };
    const level = (side: "asks" | "bids") => (row: Row, index: number, list: Row[]) => {
        const distance = side === "asks" ? list.length - 1 - index : index;
        return (<LevelRow key={row.price} row={row} side={side} distance={distance} scale={row.total / max} mounted={mounted} highlighted={hover?.side === side && distance <= hover.index} onHover={(on) => setHover(on ? { side, index: distance } : null)}/>);
    };
    return (<>
      <section ref={sectionRef} aria-label="ETH/USDC Order book" className="art:w-full art:bg-background art:px-4 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-5xl">
          <header className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-x-8 art:gap-y-4 art:rounded-3xl art:border art:border-border art:bg-background art:px-5 art:py-4">
            <div className="art:flex art:items-center art:gap-3">
              <span className="art:relative art:flex">
                <span aria-hidden="true" className="art:relative art:inline-flex art:shrink-0 art:size-9">
                  <span className="art:flex art:size-full art:items-center art:justify-center art:overflow-hidden art:rounded-full art:bg-muted art:text-foreground">
                    {COIN_ICONS.ETH}
                  </span>
                </span>
                <span aria-hidden="true" className="art:relative art:inline-flex art:shrink-0 art:-ml-3 art:size-9 art:rounded-full art:ring-2 art:ring-background">
                  <span className="art:flex art:size-full art:items-center art:justify-center art:overflow-hidden art:rounded-full art:bg-muted art:text-foreground">
                    {COIN_ICONS.USDC}
                  </span>
                </span>
              </span>
              <div>
                <h2 className="art:text-xl art:font-medium">
                  {"ETH"}
                  <span className="art:text-muted-foreground">
                    {"/"}
                    {"USDC"}
                  </span>
                </h2>
                <p className="art:text-xs art:tabular-nums art:text-emerald-600 art:dark:text-emerald-400">
                  {"+"}
                  {"2.41"}
                  {"% \u00B7 24h"}
                </p>
              </div>
            </div>
            <p className={artemisCx("art:text-3xl art:font-medium art:tracking-tight art:tabular-nums", direction === "down" ? "art:text-red-600 art:dark:text-red-400" : "art:text-emerald-600 art:dark:text-emerald-400")} aria-live="off">
              <ArtemisDigitSwap value={lastText} direction={direction}/>
            </p>
            <dl className="art:grid art:grid-cols-3 art:gap-6 art:text-xs">
              <div>
                <dt className="art:text-muted-foreground">{"24h high"}</dt>
                <dd className="art:mt-1 art:font-mono art:tabular-nums">{"2,448.9"}</dd>
              </div>
              <div>
                <dt className="art:text-muted-foreground">{"24h low"}</dt>
                <dd className="art:mt-1 art:font-mono art:tabular-nums">{"2,351.2"}</dd>
              </div>
              <div>
                <dt className="art:text-muted-foreground">{"24h volume"}</dt>
                <dd className="art:mt-1 art:font-mono art:tabular-nums">{"184,220 ETH"}</dd>
              </div>
            </dl>
          </header>
          <div className="art:mt-4 art:@min-[1024px]/artemis:hidden">
            <div role="tablist" className="art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:flex art:w-full art:*:flex-1" aria-label="Panels">
              {([
            { value: "book", label: "Order book" },
            { value: "trades", label: "Trades" },
        ] as const).map((tab) => {
            const active = panel === tab.value;
            return (<div key={tab.value} className="art:relative">
                    {active ? <Indicator id={`${id}-panel-indicator`}/> : null}
                    <button type="button" role="tab" aria-selected={active} className={artemisCx(TAB_BUTTON, "art:px-3.5", active ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground", "art:rounded-full art:h-8 art:w-full art:text-xs")} onClick={() => setPanel(tab.value)}>
                      {tab.label}
                    </button>
                  </div>);
        })}
            </div>
          </div>
          <div className="art:mt-4 art:grid art:gap-4 art:@min-[1024px]/artemis:grid-cols-5">
            <div className={artemisCx("art:overflow-clip art:rounded-3xl art:border art:border-border art:bg-background art:@min-[1024px]/artemis:col-span-3", panel === "trades" && "art:hidden art:@min-[1024px]/artemis:block")}>
              <div className="art:flex art:items-center art:justify-between art:gap-3 art:px-4 art:pt-4 art:pb-2">
                <h3 className="art:text-sm art:font-medium">{"Order book"}</h3>
                <div>
                  <div role="tablist" className="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1" aria-label="Price grouping" onKeyDown={onGroupKey}>
                    {GROUPS.map((g, index) => {
            const active = g.value === group;
            return (<div key={g.value} className="art:relative">
                          {active ? <Indicator id={`${id}-group-indicator`}/> : null}
                          <button ref={(node) => {
                    groupRefs.current[index] = node;
                }} type="button" role="tab" aria-selected={active} className={artemisCx(TAB_BUTTON, active ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground", "art:rounded-full art:h-7 art:px-2.5 art:font-mono art:text-xs")} id={`${id}-group-${g.value}`} tabIndex={active ? 0 : -1} onClick={() => setGroup(g.value)}>
                            {g.label}
                          </button>
                        </div>);
        })}
                  </div>
                </div>
              </div>
              <section aria-label="Order book, ETH/USDC" className="art:w-full art:overflow-hidden art:border-border art:bg-background art:font-mono art:text-xs art:tabular-nums art:max-w-none art:rounded-none art:border-0">
                <div aria-hidden="true" className="art:grid art:grid-cols-3 art:py-3 art:text-xs art:text-muted-foreground art:whitespace-nowrap art:tracking-normal art:normal-case">
                  <span className="art:px-4">
                    {"Price"}
                    {" (USDC)"}
                  </span>
                  <span className="art:px-4 art:text-right">
                    {"Size"}
                    {" (ETH)"}
                  </span>
                  <span className="art:px-4 art:text-right">{"Total"}</span>
                </div>
                <table aria-label="Asks · sell orders" className="art:w-full art:table-fixed art:border-separate art:border-spacing-0">
                  <SrHead />
                  <tbody>{asks.slice().reverse().map(level("asks"))}</tbody>
                </table>
                <div className="art:my-1 art:flex art:flex-wrap art:items-baseline art:justify-between art:gap-x-4 art:gap-y-1 art:border-y art:border-border art:bg-muted/40 art:px-4 art:py-3">
                  <span className="art:text-base art:font-medium art:tracking-tight">
                    <span className="art:sr-only">{"Reference price: "}</span>
                    {lastText}
                  </span>
                  <span className="art:text-xs art:text-muted-foreground">{`Spread ${spread}`}</span>
                </div>
                <table aria-label="Bids · buy orders" className="art:w-full art:table-fixed art:border-separate art:border-spacing-0">
                  <SrHead />
                  <tbody>{bids.map(level("bids"))}</tbody>
                </table>
                <p aria-live="polite" className="art:flex art:min-h-10 art:flex-wrap art:items-center art:justify-between art:gap-x-4 art:gap-y-1 art:border-t art:border-border art:px-4 art:py-2 art:text-muted-foreground">
                  {hover ? (<>
                      <span>
                        {"Avg "}
                        <span className="art:text-foreground">{formatUsd(cost / filled)}</span>
                      </span>
                      <span>
                        <span className="art:text-foreground">{`${formatSize(filled)} ETH`}</span>
                        {` \u00B7 ${formatUsd(cost)} USDC`}
                      </span>
                    </>) : (<span className="art:font-sans">{"Hover a level to see the cost of filling up to it"}</span>)}
                </p>
              </section>
            </div>
            <div className={artemisCx("art:overflow-clip art:rounded-3xl art:border art:border-border art:bg-background art:pt-4 art:@min-[1024px]/artemis:col-span-2", panel === "book" && "art:hidden art:@min-[1024px]/artemis:block")}>
              <h3 className="art:px-4 art:pb-2 art:text-sm art:font-medium">{"Trades"}</h3>
              <table className="art:w-full art:table-fixed art:border-collapse">
                <caption className="art:sr-only">{"Trades"}</caption>
                <thead>
                  <tr className="art:h-8 art:text-xs art:text-muted-foreground">
                    <th scope="col" className="art:pl-4 art:text-left art:font-normal">
                      {"Price (USDC)"}
                    </th>
                    <th scope="col" className="art:text-right art:font-normal">
                      {"Size (ETH)"}
                    </th>
                    <th scope="col" className="art:pr-4 art:text-right art:font-normal">
                      {"Time"}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <AnimatePresence initial={false}>
                    {book.trades.map((trade) => (<motion.tr key={trade.id} layout className="art:h-7 art:font-mono art:text-xs art:tabular-nums" initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={TRADE_IN}>
                        <td className={artemisCx("art:pl-4", trade.side === "sell" ? "art:text-red-600 art:dark:text-red-400" : "art:text-emerald-600 art:dark:text-emerald-400")}>
                          {formatPrice(trade.price)}
                        </td>
                        <td className="art:text-right">{formatSize(trade.size)}</td>
                        <td className="art:pr-4 art:text-right art:text-muted-foreground">{trade.time}</td>
                      </motion.tr>))}
                  </AnimatePresence>
                </tbody>
              </table>
            </div>
          </div>
          <p className="art:mt-4 art:text-xs art:text-muted-foreground">{"Simulated order flow for demonstration. Not market data."}</p>
        </div>
      </section>
    </>);
}
